// Estimate follow-up sequence: Day 1 / 3 / 7 / 14 / 21 (configurable), SMS+Email alternating.
// Stops on accept/decline/opt-out/terminal status, business-hours + daily-cap gated.
// Plain Date math for version-safety (no $DateTime).
const openH = Number($env.BUSINESS_HOURS_START || 9);
const closeH = Number($env.BUSINESS_HOURS_END || 19);
if (!($now.hour >= openH && $now.hour < closeH)) return []; // quiet/business-hours gate
const days = (($env.FOLLOWUP_DAYS || '1,3,7,14,21').split(',')).map(n => Number(n.trim())).filter(n => !isNaN(n));
const channels = (($env.FOLLOWUP_CHANNELS || 'sms,email,sms,email,sms').split(',')).map(s => s.trim().toLowerCase());
const maxSteps = days.length;
const dailyCap = Number($env.DAILY_CAP || 200);
const biz = $env.BUSINESS_NAME || 'us';
const booking = $env.BOOKING_LINK || '';
const nowMs = $now.toMillis();
const today = $now.toISODate();
const yes = v => String(v || '').toLowerCase() === 'yes';
const dateOf = v => { const t = new Date(v).getTime(); return isNaN(t) ? '' : new Date(t).toISOString().slice(0,10); };
const rows = $input.all().map(i => i.json);
// Daily cap across all quotes (count today's outbound touches).
const sentToday = rows.filter(r => r.Last_Outbound_At && dateOf(r.Last_Outbound_At) === today).length;
let remaining = Math.max(0, dailyCap - sentToday);
const terminal = s => ['won','accepted','declined','opted out','expired','lost','complete'].some(t => s.includes(t));
const out = [];
for (const r of rows) {
  if (remaining <= 0) break;
  const status = String(r.Status || '').toLowerCase();
  if (yes(r.Opted_Out)) continue;
  if (String(r.Sequence_Active || 'Yes').toLowerCase() === 'no') continue;
  if (terminal(status)) continue;
  const step = Number(r.Sequence_Step || 0);
  if (step >= maxSteps) continue;
  const phone = String(r.Customer_Phone || '').trim();
  const due = r.Next_Follow_Up_At ? nowMs >= new Date(r.Next_Follow_Up_At).getTime() : false;
  if (!due) continue;
  // Expiration guard: if the estimate has expired, stop the sequence instead of sending.
  const expMs = r.Expiration_Date ? new Date(r.Expiration_Date).getTime() : NaN;
  if (!isNaN(expMs) && expMs < nowMs) { out.push({ json: { ...r, _expired: true, _new_status: 'Expired', _next_followup_at: '', _next_step: step } }); continue; }
  const nextStep = step + 1;
  const isLast = nextStep >= maxSteps;
  const channel = channels[step] || 'sms';
  const first = r.Customer_Name ? (' ' + String(r.Customer_Name).split(' ')[0]) : '';
  const svc = r.Service_Type ? ` for your ${r.Service_Type}` : '';
  const amt = r.Estimate_Amount ? ` ($${r.Estimate_Amount})` : '';
  const expNote = r.Expiration_Date ? ` Your quote is valid through ${dateOf(r.Expiration_Date)}.` : '';
  const sms = isLast
    ? `Hi${first}, last check-in from ${biz} on your estimate${svc}${amt}. We'd still love to earn your business — reply here and we'll take care of you. ${booking}`.trim()
    : `Hi${first}, following up from ${biz} on the estimate${svc}${amt} we sent.${expNote} Any questions, or want to get scheduled? Reply here or book: ${booking}`.trim();
  const emailSubject = `Your ${biz} estimate${svc ? ' ' + r.Service_Type : ''}${amt}`;
  const emailBody = `Hi${first},\n\nJust following up on the estimate we sent you${svc}${amt}.${expNote}\n\nWe'd be glad to answer any questions or get you on the schedule — simply reply to this email${booking ? ' or book a time here: ' + booking : ''}.\n\nThanks,\n${biz}`;
  const gaps = days;
  const nextGapDays = gaps[nextStep] !== undefined ? gaps[nextStep] : 0;
  const nextAt = isLast ? '' : $now.plus({ minutes: (nextGapDays - (gaps[step] || 0)) * 1440 }).toISO();
  out.push({ json: { ...r, _channel: (channel === 'email' && r.Customer_Email) ? 'email' : 'sms', _has_phone: !!phone, _sms_msg: sms, _email_subject: emailSubject, _email_body: emailBody, _next_step: nextStep, _is_last: isLast, _next_followup_at: nextAt, _new_status: isLast ? 'Sequence Complete - No Response' : 'Follow-Up Sent', _expired: false } });
  remaining--;
}
return out;
